            case 45:  /* "-" */
            case 42:  /* "*" */
            case 47:  /* "/" */
            case 37:  /* "%" */
            case 94:  /* "^" */
            case 62:  /* ">" */
            case 60:  /* "<" */
            case 124: /* "|" */
            case 38:  /* "&" */
